/* Read-only post-apply verification. Always returns an OVERALL_RESULT row. */
SET NOCOUNT ON;
DECLARE @checks TABLE(check_name NVARCHAR(120),status NVARCHAR(10),violation_count BIGINT,details NVARCHAR(1000));
DECLARE @online SYSNAME=N'dbo.ai_l2_fault_judgment_online_v2', @view SYSNAME=N'dbo.vw_ai_dashboard_events_source_aware_v2';
INSERT @checks SELECT N'online_table_exists',CASE WHEN OBJECT_ID(@online,N'U') IS NULL THEN N'FAIL' ELSE N'PASS' END,CASE WHEN OBJECT_ID(@online,N'U') IS NULL THEN 1 ELSE 0 END,N'Required online result table';
INSERT @checks SELECT N'dashboard_view_exists',CASE WHEN OBJECT_ID(@view,N'V') IS NULL THEN N'FAIL' ELSE N'PASS' END,CASE WHEN OBJECT_ID(@view,N'V') IS NULL THEN 1 ELSE 0 END,N'Required source-aware dashboard view';
IF OBJECT_ID(@online,N'U') IS NOT NULL
BEGIN
 INSERT @checks SELECT N'required_lineage_columns',CASE WHEN COUNT(*)=5 THEN N'PASS' ELSE N'FAIL' END,5-COUNT(*),N'event_source,event_uid,l2_ready_flag,policy_ready_flag,readiness_reason' FROM sys.columns WHERE object_id=OBJECT_ID(@online) AND name IN(N'event_source',N'event_uid',N'l2_ready_flag',N'policy_ready_flag',N'readiness_reason');
 INSERT @checks SELECT N'event_source_null',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'event_source must be populated' FROM dbo.ai_l2_fault_judgment_online_v2 WHERE event_source IS NULL;
 INSERT @checks SELECT N'event_uid_null',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'event_uid must be populated' FROM dbo.ai_l2_fault_judgment_online_v2 WHERE event_uid IS NULL;
 INSERT @checks SELECT N'event_uid_source_contract',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'event_uid must equal event_source:event_id' FROM dbo.ai_l2_fault_judgment_online_v2 WHERE event_uid<>CONCAT(event_source,N':',CONVERT(NVARCHAR(30),event_id));
 INSERT @checks SELECT N'duplicate_event_uid',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'Grouped duplicate event_uid count' FROM(SELECT event_uid FROM dbo.ai_l2_fault_judgment_online_v2 GROUP BY event_uid HAVING COUNT_BIG(*) > 1)x;
 INSERT @checks SELECT N'duplicate_source_event',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'Grouped duplicate source/event count' FROM(SELECT event_source,event_id FROM dbo.ai_l2_fault_judgment_online_v2 GROUP BY event_source,event_id HAVING COUNT_BIG(*)>1)x;
 INSERT @checks SELECT N'invalid_action',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'Only LOW/MEDIUM/HIGH/CRITICAL are operational actions' FROM dbo.ai_l2_fault_judgment_online_v2 WHERE operational_action_level IS NOT NULL AND operational_action_level NOT IN(N'LOW',N'MEDIUM',N'HIGH',N'CRITICAL');
 INSERT @checks SELECT N'monitor_sensitive_action',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'MONITOR/SENSITIVE must not be stored as action' FROM dbo.ai_l2_fault_judgment_online_v2 WHERE operational_action_level IN(N'MONITOR',N'SENSITIVE');
 INSERT @checks SELECT N'l1_unready_has_score',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'L1 score forbidden for l1_ready=0' FROM dbo.ai_l2_fault_judgment_online_v2 WHERE l1_score_available_flag=0 AND (score_lenient IS NOT NULL OR score_strict IS NOT NULL);
 INSERT @checks SELECT N'l2_unready_has_probability',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'L2 probabilities forbidden for l2_ready=0' FROM dbo.ai_l2_fault_judgment_online_v2 WHERE l2_ready_flag=0 AND (risk_fault_10_events IS NOT NULL OR risk_fault_30_events IS NOT NULL OR risk_fault_30min IS NOT NULL OR risk_fault_60min IS NOT NULL OR risk_maintenance_30_events IS NOT NULL OR risk_repair_30_events IS NOT NULL);
 INSERT @checks SELECT N'policy_contract',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'Action and policy readiness must agree' FROM dbo.ai_l2_fault_judgment_online_v2 WHERE (policy_ready_flag=0 AND operational_action_level IS NOT NULL) OR (policy_ready_flag=1 AND operational_action_level IS NULL);
END
/* Schema checks derive from code-written columns, not a hand-maintained partial list. */
DECLARE @required_columns TABLE(table_name SYSNAME,column_name SYSNAME,type_name SYSNAME,nullable_allowed BIT);
INSERT @required_columns VALUES
 (N'dbo.ai_inference_checkpoint',N'pipeline_name',N'nvarchar',0),(N'dbo.ai_inference_checkpoint',N'last_event_id',N'bigint',1),(N'dbo.ai_inference_checkpoint',N'last_event_time',N'datetime2',1),(N'dbo.ai_inference_checkpoint',N'updated_time',N'datetime2',0),
 (N'dbo.ai_inference_error_log',N'runtime_run_id',N'nvarchar',1),(N'dbo.ai_inference_error_log',N'event_source',N'nvarchar',1),(N'dbo.ai_inference_error_log',N'event_id',N'bigint',1),(N'dbo.ai_inference_error_log',N'machine_id',N'int',1),(N'dbo.ai_inference_error_log',N'error_stage',N'nvarchar',1),(N'dbo.ai_inference_error_log',N'error_message',N'nvarchar',1),(N'dbo.ai_inference_error_log',N'created_time',N'datetime2',0),
 (N'dbo.ai_inference_run_log',N'runtime_run_id',N'nvarchar',1),(N'dbo.ai_inference_run_log',N'pipeline_name',N'nvarchar',0),(N'dbo.ai_inference_run_log',N'started_time',N'datetime2',0),(N'dbo.ai_inference_run_log',N'ended_time',N'datetime2',1),(N'dbo.ai_inference_run_log',N'status',N'nvarchar',1),(N'dbo.ai_inference_run_log',N'raw_candidate_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'context_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'canonical_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'l1_ready_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'l1_unready_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'l2_ready_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'l2_unready_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'policy_ready_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'inserted_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'updated_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'skipped_duplicate_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'failed_count',N'bigint',1),(N'dbo.ai_inference_run_log',N'error_summary',N'nvarchar',1),(N'dbo.ai_inference_run_log',N'model_lineage_hash',N'char',1),(N'dbo.ai_inference_run_log',N'policy_version',N'nvarchar',1),(N'dbo.ai_inference_run_log',N'sql_write_enabled',N'bit',0),
 (N'dbo.ai_l2_fault_judgment_online_v2',N'event_source',N'nvarchar',0),(N'dbo.ai_l2_fault_judgment_online_v2',N'event_uid',N'nvarchar',0),(N'dbo.ai_l2_fault_judgment_online_v2',N'event_id',N'bigint',0),(N'dbo.ai_l2_fault_judgment_online_v2',N'l1_score_available_flag',N'bit',0),(N'dbo.ai_l2_fault_judgment_online_v2',N'l2_ready_flag',N'bit',0),(N'dbo.ai_l2_fault_judgment_online_v2',N'policy_ready_flag',N'bit',0),(N'dbo.ai_l2_fault_judgment_online_v2',N'readiness_reason',N'nvarchar',1),(N'dbo.ai_l2_fault_judgment_online_v2',N'runtime_run_id',N'nvarchar',1);
INSERT @checks
SELECT CASE WHEN r.table_name=N'dbo.ai_inference_run_log' THEN N'run_log_required_columns' WHEN r.table_name=N'dbo.ai_inference_checkpoint' THEN N'checkpoint_required_columns' WHEN r.table_name=N'dbo.ai_inference_error_log' THEN N'error_log_required_columns' ELSE N'online_result_required_columns' END,
 CASE WHEN SUM(CASE WHEN c.column_id IS NULL OR t.name<>r.type_name OR (r.nullable_allowed=0 AND c.is_nullable=1) THEN 1 ELSE 0 END)=0 THEN N'PASS' ELSE N'FAIL' END,
 SUM(CASE WHEN c.column_id IS NULL OR t.name<>r.type_name OR (r.nullable_allowed=0 AND c.is_nullable=1) THEN 1 ELSE 0 END),N'Code-required name/type/nullability contract'
FROM @required_columns r LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(r.table_name) AND c.name=r.column_name LEFT JOIN sys.types t ON t.user_type_id=c.user_type_id GROUP BY r.table_name;
IF OBJECT_ID(N'dbo.ai_inference_run_log',N'U') IS NOT NULL
BEGIN
 INSERT @checks SELECT N'new_run_runtime_id',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'New runtime rows require runtime_run_id' FROM dbo.ai_inference_run_log WHERE runtime_run_id IS NULL AND raw_candidate_count IS NOT NULL;
 INSERT @checks SELECT N'new_run_runtime_id_duplicate',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'No duplicate non-null runtime id' FROM(SELECT runtime_run_id FROM dbo.ai_inference_run_log WHERE runtime_run_id IS NOT NULL GROUP BY runtime_run_id HAVING COUNT_BIG(*)>1)x;
 INSERT @checks SELECT N'new_run_nonnegative_counts',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'New count fields are nonnegative' FROM dbo.ai_inference_run_log WHERE runtime_run_id IS NOT NULL AND (raw_candidate_count<0 OR context_count<0 OR canonical_count<0 OR l1_ready_count<0 OR l1_unready_count<0 OR l2_ready_count<0 OR l2_unready_count<0 OR policy_ready_count<0 OR inserted_count<0 OR updated_count<0 OR skipped_duplicate_count<0 OR failed_count<0);
 INSERT @checks SELECT N'new_run_time_order',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'Completed runtime run ends after it starts' FROM dbo.ai_inference_run_log WHERE runtime_run_id IS NOT NULL AND (ended_time IS NULL OR ended_time<started_time);
 INSERT @checks SELECT N'new_run_status',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'Controlled writer currently emits SUCCESS only' FROM dbo.ai_inference_run_log WHERE runtime_run_id IS NOT NULL AND status NOT IN(N'SUCCESS');
 INSERT @checks SELECT N'new_run_write_flag',CASE WHEN COUNT_BIG(*)=0 THEN N'PASS' ELSE N'FAIL' END,COUNT_BIG(*),N'sql_write_enabled must be 0 or 1' FROM dbo.ai_inference_run_log WHERE runtime_run_id IS NOT NULL AND sql_write_enabled NOT IN(0,1);
END
SELECT check_name,status,violation_count,details FROM @checks ORDER BY check_name;
SELECT N'OVERALL_RESULT' AS check_name,CASE WHEN EXISTS(SELECT 1 FROM @checks WHERE status=N'FAIL') THEN N'FAIL' ELSE N'PASS' END AS status,COALESCE((SELECT SUM(violation_count) FROM @checks WHERE status=N'FAIL'),0) AS violation_count,N'All dashboard contract checks' AS details;
